'use client'

import Link from 'next/link'
import Image from 'next/image'
import toast, { Toaster } from 'react-hot-toast'
import { useEffect, useState } from 'react'
import { useFormStatus } from 'react-dom'
import { getClaim, getChillwhale } from '../../util/api'
import ABI from './../../abi/chillwhale.json'
import { useAuth, provider } from '../../contexts/AuthContext'
import Icon from '../../helper/MaterialIcon'
import Web3 from 'web3'
import moment from 'moment-timezone'
import DefaultPFP from './../../public/default-pfp.svg'
import PageTitle from '../../components/PageTitle'
import Shimmer from '../../helper/Shimmer'
import styles from './page.module.scss'

export default function Page({ params, searchParams }) {
  const [claim, setClaim] = useState([])
  const [chillwhale, setChillwhale] = useState([])
  const [chillwhaleData, setChillwhaleData] = useState([])
  const [options, setOptions] = useState({ list: [`Choice 1`, `Choice 2`, `Choice 3`] })
    const [profiles, setProfiles] = useState()
  // const filter = await searchParams
  // const page = filter.page
  // const product = await getProductList(filter)
  const auth = useAuth()

  const web3Readonly = new Web3(process.env.NEXT_PUBLIC_LUKSO_PROVIDER)
  const _ = web3Readonly.utils
  const contractReadonly = new web3Readonly.eth.Contract(ABI, process.env.NEXT_PUBLIC_CONTRACT)

  const fetchData = async (dataURL) => {
    let requestOptions = {
      method: 'GET',
      redirect: 'follow',
    }
    const response = await fetch(`${dataURL}`, requestOptions)
    if (!response.ok) throw new Response('Failed to get data', { status: 500 })
    return response.json()
  }

  // function numberToBytes32(number) {
  //   const hex = web3Readonly.utils.toHex(number);
  //   return web3Readonly.utils.padLeft(hex, 64);
  // }

  const getChillwhaleData = async (addresses) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  Asset(
    limit: 30
    where: {isLSP7: {_eq: false}, id: {_eq: "0x86e817172b5c07f7036bf8aa46e2db9063743a83"}}
  ) {
    id
    isLSP7
    lsp4TokenName
    lsp4TokenSymbol
    lsp4TokenType
    name
    totalSupply
    owner_id
    tokens(where: {formattedTokenId: {_in: ${JSON.stringify(addresses)}}}) {
      id
      formattedTokenId
      name
      images(limit: 1) {
        src
      }
      holders {
        profile_id
        profile {
          fullName
          profileImages(limit: 1) {
            src
          }
        }
      }
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    return data
  }

  const getAllUserReaction = async () => await contractReadonly.methods.getAllUserReaction(`0x0D5C8B7cC12eD8486E1E0147CC0c3395739F138d`).call()//${auth.contextAccounts[0]}


  const getProfile = async (addr) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  search_profiles(
    args: {search: "${addr}"}
    limit: 1
  ) {
    fullName
    name
    description
    id
    profileImages {
      src
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    return data
  }
  useEffect(() => {

    getAllUserReaction().then(async (res) => {
      console.log(res)

      if (res.length > 0) setReact(res)

      let responses_with_profile = []
      await Promise.all(
        res.map(async (response, i) => {
          return getProfile(response.sender).then((profile) => {
            responses_with_profile.push(Object.assign(profile, response))
          })
        })
      )

      setProfiles(responses_with_profile)
    })
  }, [])

  return (
    <div className={`${styles.page} ms-motion-slideDownIn`}>
      <PageTitle title={`Claim`} path={`../`} />

      <div className={`__container`} data-width={`medium`}>

        {profiles && profiles.length > 0 && (
          <div className={`${styles.profiles} grid grid--fill grid--gap-1 w-100 `} style={{ '--data-width': `32px` }}>
            {profiles.map((profile, i) => {
              return (
                <a key={i} target={`_blank`} href={`https://universaleverything.io/${profile.sender}`}>
                  <span>{emoji && emoji.filter((filterItem) => filterItem.emojiId === profile.emojiId)[0].emoji}</span>
                  {profile.data.search_profiles[0].profileImages.length > 0 ? (
                    <img
                      className={`rounded ms-depth-16`}
                      alt={profile?.LSP3Profile?.name}
                      title={_.toUtf8(profile.message)}
                      src={`${profile.data.search_profiles[0].profileImages[0].src}`}
                    />
                  ) : (
                    <img className={`rounded ms-depth-16`} alt={``} title={_.toUtf8(profile.message)} src={`https://universaleverything.io/assets/images/profile-default.svg`} />
                  )}
                </a>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}
/**
 * Profile
 * @param {String} addr
 * @returns
 */
const Profile = ({ addr }) => {
  const [data, setData] = useState()

  const getProfile = async (addr) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  search_profiles(
    args: {search: "${addr}"}
    limit: 1
  ) {
    fullName
    name
    id
    profileImages {
      src
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    setData(data)
    return data
  }

  useEffect(() => {
    getProfile(addr).then(console.log)
  }, [])

  if (!data)
    return (
      <>
        <figure className={`${styles.pfp} d-f-c flex-column grid--gap-050`}>
          <img alt={`Default PFP`} src={DefaultPFP.src} className={`rounded`} />
          <figcaption>@username</figcaption>
        </figure>
      </>
    )

  return (
    <>
      <figure className={`${styles.pfp} d-f-c flex-column grid--gap-050`}>
        <img
          alt={data.data.search_profiles[0].fullName}
          src={`${data.data.search_profiles[0].profileImages.length > 0 ? data.data.search_profiles[0].profileImages[0].src : 'https://ipfs.io/ipfs/bafkreiatl2iuudjiq354ic567bxd7jzhrixf5fh5e6x6uhdvl7xfrwxwzm'}`}
          className={`rounded`}
        />
        <figcaption>@{data.data.search_profiles[0].name}</figcaption>
      </figure>
    </>
  )
}
